{
  "interpretation": {
    "name": "SpecialFastenerTighteningNR7Line1F25",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Bring NR7 from the crib to station st1, tighten the F25 fasteners per the MES program, evaluate and record the result, then return NR7 to the crib and release it.",
    "constraints": [
      "NR7 must be reserved before any tool-using step, and those steps depend on the reserve-tool step so the lease is renewed (E6)",
      "transport-tool is delegated to agvexecutor (E2)",
      "NR7 must be at st1 before configure-tool and tighten-fasteners (E3)",
      "The tightening program comes only from get-program for variant F25, with no literal torque or tolerance values (E4)",
      "The tightening must be evaluated and recorded (E5)",
      "NR7 must be returned to the crib before the reservation is released, so no one else gets a tool that is not at the crib (E1)"
    ],
    "preference": "Release the tool as soon as it is back in the crib so other requesters do not wait.",
    "priority": "normal",
    "horizon": "Single job for the upcoming F25 at station 1",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "nr7-line1-f25-tightening",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "Deliver",
        "steps": [
          {"name": "reserve-nr7", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "get-f25-program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Deliver",
        "next": "Tighten",
        "steps": [
          {"name": "transport-nr7-to-station", "service": "transport-tool", "next": [], "dep": ["reserve-nr7"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "Tighten",
        "next": "Return",
        "steps": [
          {"name": "configure-nr7", "service": "configure-tool", "next": ["tighten-f25"], "dep": ["reserve-nr7", "get-f25-program"], "executor": null, "params": {}},
          {"name": "tighten-f25", "service": "tighten-fasteners", "next": ["evaluate-f25", "record-f25"], "dep": ["reserve-nr7", "configure-nr7"], "executor": null, "params": {}},
          {"name": "evaluate-f25", "service": "evaluate-tightening", "next": [], "dep": ["tighten-f25", "get-f25-program"], "executor": null, "params": {}},
          {"name": "record-f25", "service": "record-tightening", "next": [], "dep": ["tighten-f25"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Return",
        "next": null,
        "steps": [
          {"name": "transport-nr7-to-crib", "service": "transport-tool", "next": ["release-nr7"], "dep": ["reserve-nr7"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release-nr7", "service": "release-tool", "next": [], "dep": ["reserve-nr7"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
